// Authored public explanations, not a forecast, calibration or new score model.
// Match complete requests only: never discard a place, date, value or qualifier.
import {validateRavAssistantSourceIds} from './rav-assistant-sources-v1.js';

export const RAV_ASSISTANT_METHOD_GUIDE=Object.freeze([
  concept('ensemble',[['ensembleprognose'],['Ensemblevorhersage'],['ensemble forecast']],
    ['Hvad er en ensembleprognose?','Was ist eine Ensemblevorhersage?','What is an ensemble forecast?'],
    ['En ensembleprognose samler flere modelkørsler med varierede udgangsbetingelser eller modelbeskrivelser. De viser mulige forløb, ikke sikre udfald. Begrebet hjælper med at forstå prognoseusikkerhed; RavRadars scoreinterval må ikke af den grund kaldes et ensemble eller en procentchance for rav.',
     'Eine Ensemblevorhersage umfasst mehrere Modellläufe mit variierten Anfangsbedingungen oder Modellbeschreibungen. Sie zeigen mögliche Verläufe, keine sicheren Ergebnisse. Das erklärt Vorhersageunsicherheit; RavRadars Scoreintervall wird dadurch weder zum Ensemble noch zur prozentualen Fundchance.',
     'An ensemble forecast combines model runs with varied starting conditions or model descriptions. These show possible developments, not certain outcomes. The concept explains forecast uncertainty; it does not make RavRadar’s score interval an ensemble or a percentage chance of finding amber.'],['metoffice-ensemble-method']),
  concept('deterministic',[['deterministisk prognose'],['deterministische Vorhersage'],['deterministic forecast']],
    ['Hvad er en deterministisk prognose?','Was ist eine deterministische Vorhersage?','What is a deterministic forecast?'],
    ['En deterministisk prognose viser ét beregnet forløb fra et bestemt modeludgangspunkt. Ét forløb er ikke en garanti, selv om det vises med præcise tal. Når du læser RavRadar, skal du fortsat skelne mellem beregnede forhold og det, du faktisk ser på stranden.',
     'Eine deterministische Vorhersage zeigt einen berechneten Verlauf aus einem bestimmten Modellzustand. Ein einzelner Verlauf ist trotz genauer Zahlen keine Garantie. Unterscheide bei RavRadar weiterhin berechnete Bedingungen von dem, was du tatsächlich am Strand beobachtest.',
     'A deterministic forecast shows one calculated development from a particular model state. One development is not a guarantee, even when displayed with precise numbers. When reading RavRadar, still distinguish calculated conditions from what you actually observe on the beach.'],['metoffice-numerical-grids']),
  concept('ensemble-spread',[['ensemblespredning'],['Ensemblestreuung'],['ensemble spread']],
    ['Hvad er ensemblespredning?','Was ist Ensemblestreuung?','What is ensemble spread?'],
    ['Ensemblespredning beskriver forskellene mellem ensemblets modelmedlemmer. Stor spredning peger på forskellige mulige forløb; lille spredning udelukker ikke fælles modelfejl. Det er ikke et mål for ravmængde, og et RavScore-interval kan ikke uden videre fortolkes som denne spredning.',
     'Ensemblestreuung beschreibt Unterschiede zwischen den Modellmitgliedern. Große Streuung zeigt unterschiedliche mögliche Verläufe; geringe Streuung schließt gemeinsame Modellfehler nicht aus. Sie misst keine Bernsteinmenge. Ein RavScore-Intervall lässt sich nicht einfach als diese Streuung interpretieren.',
     'Ensemble spread describes differences between model members. Wide spread indicates differing possible developments; narrow spread does not exclude shared model errors. It is not an amber-quantity measure, and a RavScore interval cannot simply be interpreted as this spread.'],['metoffice-ensemble-method']),
  concept('initial-state',[['modellens begyndelsestilstand','modelbegyndelsestilstand'],['Modellanfangszustand'],['model initial state']],
    ['Hvad er modellens begyndelsestilstand?','Was ist ein Modellanfangszustand?','What is a model initial state?'],
    ['Begyndelsestilstanden er modellens beskrivelse af forholdene, når en beregning starter. Den bygger på et begrænset datagrundlag og er ikke en perfekt kopi af naturen. En ny vejrhentning i RavRadar henter modelresultater; den er ikke i sig selv en ny måling ved hver strand.',
     'Der Anfangszustand beschreibt die Bedingungen beim Start einer Modellberechnung. Er beruht auf begrenzten Daten und ist keine perfekte Kopie der Natur. Eine neue Wetterabfrage in RavRadar lädt Modellergebnisse; sie ist nicht selbst eine neue Messung an jedem Strand.',
     'The initial state describes conditions at the start of a model calculation. It uses limited information and is not a perfect copy of nature. A new RavRadar weather retrieval obtains model results; it is not itself a new measurement at every beach.'],['metoffice-assimilation-method']),
  concept('assimilation',[['dataassimilation'],['Datenassimilation'],['data assimilation']],
    ['Hvad er dataassimilation?','Was ist Datenassimilation?','What is data assimilation?'],
    ['Dataassimilation kombinerer observationer og tidligere modelberegninger til en sammenhængende begyndelsestilstand. Det betyder ikke, at alle modelpunkter er målt. RavRadar bruger sine eksisterende datakilder; forklaringen tilføjer hverken en ny kilde eller direkte observationer til strømpilen.',
     'Datenassimilation verbindet Beobachtungen und vorherige Modellberechnungen zu einem konsistenten Anfangszustand. Nicht jeder Modellpunkt ist deshalb gemessen. RavRadar nutzt seine bestehenden Quellen; diese Erklärung ergänzt weder eine neue Quelle noch direkte Beobachtungen für den Strömungspfeil.',
     'Data assimilation combines observations and earlier model calculations into a consistent initial state. It does not mean every model point was measured. RavRadar uses its existing sources; this explanation adds neither a source nor direct observations to the current arrow.'],['metoffice-assimilation-method']),
  concept('model-grid',[['modelgrid','modelgitter'],['Modellgitter'],['model grid']],
    ['Hvad er et modelgrid?','Was ist ein Modellgitter?','What is a model grid?'],
    ['Et modelgrid er de beregningspunkter eller celler, som en model beskriver området med. Små revlepassager og kystknæk kan være finere end modellens opløsning. Zoom på RavRadars kort ændrer ikke den underliggende modelopløsning og gør ikke strømpilen til en måling i brændingen.',
     'Ein Modellgitter besteht aus den Rechenpunkten oder Zellen, die das Gebiet beschreiben. Kleine Sandbanklücken und Küstenknicke können feiner als die Modellauflösung sein. Zoomen in RavRadar ändert die Modellauflösung nicht und macht den Strömungspfeil nicht zur Messung in der Brandung.',
     'A model grid consists of the calculation points or cells used to represent an area. Small bar gaps and coastal bends may be finer than its resolution. Zooming RavRadar’s map does not change the underlying model resolution or turn the current arrow into a surf-zone measurement.'],['metoffice-numerical-grids']),
  concept('boundary-conditions',[['modellens randbetingelser','modelrandbetingelser'],['Modellrandbedingungen'],['model boundary conditions']],
    ['Hvad er modellens randbetingelser?','Was sind Modellrandbedingungen?','What are model boundary conditions?'],
    ['Randbetingelser beskriver påvirkningen ved grænserne af et modelområde; en regional model kan få dem fra en større model. Lokalt detaljerede beregninger kan derfor stadig afhænge af omgivelserne. Begrebet er ikke en tilladelse til at udvide en kildes gyldige domæne eller blande andre data ind i RavRadar.',
     'Randbedingungen beschreiben Einflüsse an den Grenzen eines Modellgebiets; ein Regionalmodell kann sie von einem größeren Modell erhalten. Auch örtlich detaillierte Berechnungen hängen damit von der Umgebung ab. Das erlaubt weder die Erweiterung eines gültigen Quelldomäns noch das Beimischen anderer Daten in RavRadar.',
     'Boundary conditions describe influences at a model domain’s edges; a regional model may obtain them from a larger model. Detailed local calculations can therefore still depend on their surroundings. This does not authorise extending a source’s valid domain or mixing other data into RavRadar.'],['metoffice-numerical-grids']),
  concept('reanalysis',[['reanalyse'],['Reanalyse'],['reanalysis']],
    ['Hvad er en reanalyse?','Was ist eine Reanalyse?','What is a reanalysis?'],
    ['En reanalyse rekonstruerer tidligere vejr med observationer og genkørte modeller. Den er hverken ren målehistorik eller nødvendigvis den prognose, der blev udstedt dengang. Ved vurdering af en gammel ravtur skal oprindelig prognose og senere rekonstruktion holdes adskilt. Forklaringen installerer ikke reanalysedata i RavRadar.',
     'Eine Reanalyse rekonstruiert früheres Wetter mit Beobachtungen und erneut gerechneten Modellen. Sie ist weder reine Messhistorie noch zwingend die damals ausgegebene Vorhersage. Halte bei alten Bernsteintouren ursprüngliche Prognose und spätere Rekonstruktion auseinander. Diese Erklärung installiert keine Reanalysedaten in RavRadar.',
     'Reanalysis reconstructs past weather using observations and rerun models. It is neither an observation-only record nor necessarily the forecast originally issued. Keep the original forecast separate from later reconstruction when assessing an old amber trip. This explanation installs no reanalysis data in RavRadar.'],['ecmwf-reanalysis-method']),
  concept('nowcast',[['nowcasting','nowcast'],['Nowcasting','Nowcast'],['nowcasting','nowcast']],
    ['Hvad er nowcasting?','Was ist Nowcasting?','What is nowcasting?'],
    ['Nowcasting er meget kortfristet, lokalt detaljeret vejrprognose fra nu og få timer frem, ofte med tæt brug af observationer. Det er ikke det samme som en femdages prognose. RavRadar får ikke en særskilt nowcast eller hurtigere opdatering, blot fordi assistenten forklarer ordet.',
     'Nowcasting ist eine sehr kurzfristige, örtlich detaillierte Wettervorhersage ab jetzt für wenige Stunden, oft mit intensiver Nutzung von Beobachtungen. Das ist keine Fünf-Tage-Prognose. RavRadar erhält durch diese Worterklärung weder einen eigenen Nowcast noch schnellere Aktualisierungen.',
     'Nowcasting is very short-range, locally detailed weather forecasting from now to a few hours ahead, often relying closely on observations. It is not a five-day forecast. Explaining the term does not give RavRadar a separate nowcast or faster updates.'],['metoffice-nowcasting-method']),
  concept('forecast-lead-time',[['prognosens fremskrivningstid','prognoseleadtime'],['Vorhersagevorlaufzeit'],['forecast lead time']],
    ['Hvad er prognosens fremskrivningstid?','Was ist die Vorhersagevorlaufzeit?','What is forecast lead time?'],
    ['Fremskrivningstiden er tiden fra modellens start til det tidspunkt, prognosen gælder for. Den er ikke det samme som hjemmesidens opdateringsalder. Usikkerhed kan ændre sig længere fremme i forløbet; forklaringen beregner ikke en ny usikkerhedsprocent for morgendagens ravtur.',
     'Die Vorlaufzeit reicht vom Modellstart bis zum Zeitpunkt, für den die Vorhersage gilt. Sie ist nicht das Alter der Websiteaktualisierung. Unsicherheit kann sich im weiteren Verlauf ändern; diese Erklärung berechnet keine neue Unsicherheitsquote für die morgige Bernsteintour.',
     'Lead time runs from model initialisation to the time the forecast applies to. It is not the age of the website update. Uncertainty can change farther into a forecast; this explanation calculates no new uncertainty percentage for tomorrow’s amber trip.'],['metoffice-ensemble-method','metoffice-numerical-grids']),
  concept('measurement-accuracy',[['målenøjagtighed'],['Messgenauigkeit'],['measurement accuracy']],
    ['Hvad er målenøjagtighed?','Was ist Messgenauigkeit?','What is measurement accuracy?'],
    ['Målenøjagtighed handler om nærhed til den værdi, man ønsker at måle. Mange decimaler beviser ikke nøjagtighed. Et flot tal på RavRadar må derfor ikke behandles som en perfekt strandmåling eller som dokumentation for, hvor mange ravstykker der ligger der.',
     'Messgenauigkeit betrifft die Nähe zum Wert der zu messenden Größe. Viele Dezimalstellen beweisen keine Genauigkeit. Eine präzise dargestellte Zahl in RavRadar ist daher weder eine perfekte Strandmessung noch ein Nachweis der dort liegenden Bernsteinstücke.',
     'Measurement accuracy concerns closeness to the value being measured. Many decimal places do not prove accuracy. A neatly displayed RavRadar number must not be treated as a perfect beach measurement or evidence of how many amber pieces are there.'],['nist-measurement-terminology']),
  concept('measurement-precision',[['målepræcision'],['Messpräzision'],['measurement precision']],
    ['Hvad er målepræcision?','Was ist Messpräzision?','What is measurement precision?'],
    ['Målepræcision handler om, hvor tæt gentagne måleresultater ligger. De kan ligge tæt og alligevel være forskudt i samme retning. Gentagne ens prognoseværdier i RavRadar er heller ikke automatisk uafhængige målinger eller bevis på, at modellen rammer den lokale strand.',
     'Messpräzision betrifft die Übereinstimmung wiederholter Messergebnisse. Sie können eng beieinanderliegen und trotzdem gemeinsam verschoben sein. Wiederholt gleiche Prognosewerte in RavRadar sind ebenfalls nicht automatisch unabhängige Messungen oder ein Beweis für richtige örtliche Bedingungen.',
     'Measurement precision concerns agreement between repeated measurements. They can agree closely yet share an offset. Repeated identical RavRadar forecast values are not automatically independent measurements or proof that the model represents the local beach correctly.'],['nist-measurement-terminology']),
  comparison('accuracy-precision',[['målenøjagtighed','Messgenauigkeit','measurement accuracy'],['målepræcision','Messpräzision','measurement precision']],
    ['Hvad er forskellen på målenøjagtighed og målepræcision?','Was ist der Unterschied zwischen Messgenauigkeit und Messpräzision?','What is the difference between measurement accuracy and measurement precision?'],
    ['Nøjagtighed vedrører nærhed til den ønskede måleværdi; præcision vedrører gentagne resultaters indbyrdes enighed. Et instrument kan være præcist uden at være nøjagtigt. At en RavRadar-værdi gentages, eller vises med mange decimaler, beviser hverken en korrekt lokal strøm eller en fundchance.',
     'Genauigkeit betrifft die Nähe zum gesuchten Messwert; Präzision die Übereinstimmung wiederholter Ergebnisse. Ein Instrument kann präzise sein, ohne genau zu sein. Wiederholte RavRadar-Werte oder viele Dezimalstellen belegen weder die richtige örtliche Strömung noch eine Fundchance.',
     'Accuracy concerns closeness to the target value; precision concerns agreement between repeated results. An instrument may be precise without being accurate. Repeated RavRadar values or many decimal places prove neither a correct local current nor a chance of finding amber.'],['nist-measurement-terminology']),
  concept('repeatability',[['målingers gentagelighed'],['Wiederholpräzision'],['measurement repeatability']],
    ['Hvad er målingers gentagelighed?','Was ist Wiederholpräzision?','What is measurement repeatability?'],
    ['Gentagelighed beskriver resultaters enighed under samme målebetingelser. Ved ravture skal metode, søgetid og undersøgt strækning derfor beskrives, før man sammenligner gentagelser. To ture med forskellig indsats er ikke en kontrolleret gentagelse, og samme vejr betyder ikke samme tilgængelige ravlager.',
     'Wiederholpräzision beschreibt Ergebnisübereinstimmung bei gleichen Messbedingungen. Dokumentiere bei Bernsteintouren daher Methode, Suchdauer und untersuchten Abschnitt, bevor du Wiederholungen vergleichst. Unterschiedlicher Aufwand ist keine kontrollierte Wiederholung; gleiches Wetter bedeutet auch keinen gleichen zugänglichen Bernsteinvorrat.',
     'Repeatability describes agreement under the same measurement conditions. Record method, search time and the investigated stretch before comparing repeat amber trips. Different effort is not a controlled repeat, and identical weather does not mean the same accessible amber stock.'],['nist-measurement-terminology']),
  concept('reproducibility',[['målingers reproducerbarhed'],['Vergleichspräzision'],['measurement reproducibility']],
    ['Hvad er målingers reproducerbarhed?','Was ist Vergleichspräzision?','What is measurement reproducibility?'],
    ['Reproducerbarhed undersøger resultaters enighed, når angivne betingelser ændres, fx observatør eller instrument. Forskellige ravjægeres erfaring og metode skal derfor fremgå af en sammenligning. En forskel i fund er ikke alene bevis på en fejl i RavRadar; både indsats, forhold og tilgængeligt materiale kan variere.',
     'Vergleichspräzision untersucht Ergebnisübereinstimmung bei geänderten, angegebenen Bedingungen, etwa Beobachter oder Instrument. Erfahrung und Methode verschiedener Bernsteinsucher gehören deshalb in einen Vergleich. Unterschiedliche Funde beweisen allein keinen RavRadar-Fehler; Aufwand, Bedingungen und verfügbares Material können variieren.',
     'Reproducibility examines agreement when specified conditions change, such as observer or instrument. A comparison between amber hunters should therefore describe their experience and methods. Different finds alone do not prove a RavRadar fault; effort, conditions and available material can all differ.'],['nist-measurement-terminology']),
  concept('random-error',[['tilfældig målefejl'],['zufälliger Messfehler'],['random measurement error']],
    ['Hvad er en tilfældig målefejl?','Was ist ein zufälliger Messfehler?','What is a random measurement error?'],
    ['En tilfældig målefejl varierer uforudsigeligt mellem gentagelser. Gentagne målinger kan hjælpe med at beskrive variationen, men fjerner ikke nødvendigvis en fælles skævhed. Timetal fra samme RavRadar-modelkørsel må ikke blot tælles som nye uafhængige forsøg.',
     'Ein zufälliger Messfehler verändert sich unvorhersehbar zwischen Wiederholungen. Wiederholte Messungen helfen, die Streuung zu beschreiben, beseitigen aber nicht unbedingt eine gemeinsame Verzerrung. Stundenwerte aus demselben RavRadar-Modelllauf sind nicht einfach neue unabhängige Versuche.',
     'A random measurement error varies unpredictably between repeats. Repeated measurements can describe variability but do not necessarily remove a shared bias. Hourly values from the same RavRadar model run must not simply be counted as new independent trials.'],['nist-measurement-terminology']),
  concept('systematic-error',[['systematisk målefejl'],['systematischer Messfehler'],['systematic measurement error']],
    ['Hvad er en systematisk målefejl?','Was ist ein systematischer Messfehler?','What is a systematic measurement error?'],
    ['En systematisk målefejl gentager en påvirkning på resultaterne. Flere aflæsninger alene retter den ikke. Et vedvarende misforhold mellem model og strand kræver en konkret årsagsanalyse; det berettiger ikke et gættet lokalt korrektionsled, flytning af punkter eller en automatisk ændring af RavScore.',
     'Ein systematischer Messfehler bewirkt einen wiederkehrenden Einfluss auf Ergebnisse. Weitere Ablesungen allein korrigieren ihn nicht. Dauerhafte Unterschiede zwischen Modell und Strand verlangen eine konkrete Ursachenanalyse, keinen geratenen örtlichen Korrekturwert, keine Punktverschiebung und keine automatische RavScore-Änderung.',
     'A systematic measurement error introduces a recurring influence on results. More readings alone do not correct it. A persistent model–beach mismatch calls for a concrete cause investigation, not a guessed local correction, relocated points or an automatic RavScore change.'],['nist-measurement-terminology']),
  concept('measurement-uncertainty',[['måleusikkerhed'],['Messunsicherheit'],['measurement uncertainty']],
    ['Hvad er måleusikkerhed?','Was ist Messunsicherheit?','What is measurement uncertainty?'],
    ['Måleusikkerhed beskriver den begrundede usikkerhed knyttet til et måleresultat. Den er ikke det samme som en kendt fejl eller en fundprocent. En generel definition giver ikke tal for RavRadars lokale modelfejl; en sådan vurdering kræver passende data og dokumenteret metode.',
     'Messunsicherheit beschreibt die begründete Unsicherheit eines Messergebnisses. Sie ist weder ein bekannter Fehler noch eine Fundquote. Eine allgemeine Definition liefert keine Zahlen für örtliche RavRadar-Modellfehler; dafür braucht es geeignete Daten und eine dokumentierte Methode.',
     'Measurement uncertainty describes the supported uncertainty attached to a measurement result. It is not a known error or a find percentage. A general definition supplies no numbers for RavRadar’s local model error; that assessment requires suitable data and a documented method.'],['nist-uncertainty-classification']),
  concept('type-a-uncertainty',[['type A-usikkerhed','type A evaluering'],['Typ-A-Auswertung'],['type A uncertainty evaluation']],
    ['Hvad er type A-usikkerhed?','Was ist eine Typ-A-Auswertung?','What is type A uncertainty evaluation?'],
    ['Type A er statistisk evaluering af usikkerhed ud fra data. Det er en evalueringsmetode, ikke blot et andet navn for tilfældig fejl. Mange timer fra samme vejrhændelse kan være afhængige. Assistenten må derfor ikke opfinde en sikker fejlmargin ved bare at tælle prognosetimer.',
     'Typ A ist die statistische Auswertung von Unsicherheit anhand von Daten. Das bezeichnet eine Auswertungsmethode, nicht einfach zufälligen Fehler. Viele Stunden desselben Wetterereignisses können abhängig sein. Der Assistent darf daher nicht durch bloßes Zählen von Prognosestunden eine sichere Fehlerspanne erfinden.',
     'Type A evaluates uncertainty statistically using data. It names an evaluation method, not merely random error. Many hours from one weather event may be dependent. The assistant must therefore not invent a reliable error margin by merely counting forecast hours.'],['nist-type-a-evaluation','nist-uncertainty-classification']),
  concept('type-b-uncertainty',[['type B-usikkerhed','type B evaluering'],['Typ-B-Auswertung'],['type B uncertainty evaluation']],
    ['Hvad er type B-usikkerhed?','Was ist eine Typ-B-Auswertung?','What is type B uncertainty evaluation?'],
    ['Type B vurderer usikkerhed med anden information end en statistisk analyse af de aktuelle gentagelser, fx referenceoplysninger eller instrumentdata. Den kræver begrundet viden, ikke et vilkårligt skøn. Den er heller ikke synonym med systematisk fejl eller en tilladelse til at sætte en ny margin på RavScore.',
     'Typ B beurteilt Unsicherheit mit anderer Information als einer statistischen Analyse aktueller Wiederholungen, etwa Referenz- oder Instrumentangaben. Das verlangt begründetes Wissen, keine beliebige Schätzung. Es ist weder ein Synonym für systematischen Fehler noch eine Erlaubnis für neue RavScore-Spannen.',
     'Type B evaluates uncertainty using information other than statistical analysis of the current repeats, such as reference or instrument information. It needs justified knowledge, not an arbitrary guess. It is neither synonymous with systematic error nor permission to add a new RavScore margin.'],['nist-type-b-evaluation','nist-uncertainty-classification']),
  concept('uncertainty-budget',[['usikkerhedsbudget'],['Unsicherheitsbudget'],['uncertainty budget']],
    ['Hvad er et usikkerhedsbudget?','Was ist ein Unsicherheitsbudget?','What is an uncertainty budget?'],
    ['Et usikkerhedsbudget dokumenterer bidrag til usikkerheden og hvordan de er vurderet. Det gør grundlaget gennemskueligt; ukendte bidrag bliver ikke automatisk nul. For RavRadar er dette et metodebegreb, ikke en ny beregnet tabel eller en skjult omvægtning af manglende datakilder.',
     'Ein Unsicherheitsbudget dokumentiert Unsicherheitsbeiträge und ihre Bewertung. Es macht die Grundlage nachvollziehbar; unbekannte Beiträge werden nicht automatisch null. Bei RavRadar ist das ein Methodenbegriff, keine neu berechnete Tabelle und keine versteckte Neugewichtung fehlender Datenquellen.',
     'An uncertainty budget documents contributions to uncertainty and how they were evaluated. It makes the basis traceable; unknown contributions do not automatically become zero. In RavRadar this is a method concept, not a newly calculated table or hidden reweighting of missing sources.'],['nist-uncertainty-reporting']),
  concept('coverage-factor',[['dækningsfaktor ved måling'],['Erweiterungsfaktor bei Messungen'],['measurement coverage factor']],
    ['Hvad er en dækningsfaktor ved måling?','Was ist ein Erweiterungsfaktor bei Messungen?','What is a measurement coverage factor?'],
    ['En dækningsfaktor bruges ved angivelse af udvidet måleusikkerhed. En procentfortolkning kræver et passende statistisk grundlag. Den må ikke forveksles med RavRadars datadækning, og et scoreinterval bliver ikke et 95-procents konfidensinterval, blot fordi det har to endepunkter.',
     'Ein Erweiterungsfaktor wird bei erweiterter Messunsicherheit verwendet. Eine prozentuale Interpretation braucht eine geeignete statistische Grundlage. Er ist nicht RavRadars Datenabdeckung; zwei Endpunkte machen ein Scoreintervall nicht zum 95-Prozent-Konfidenzintervall.',
     'A coverage factor is used when reporting expanded measurement uncertainty. A percentage interpretation needs an appropriate statistical basis. It is not RavRadar’s data coverage, and two endpoints do not turn a score interval into a 95-percent confidence interval.'],['nist-uncertainty-reporting']),
  concept('uncertainty-report',[['rapportering af måleusikkerhed'],['Angabe von Messunsicherheit'],['reporting measurement uncertainty']],
    ['Hvad betyder rapportering af måleusikkerhed?','Was bedeutet die Angabe von Messunsicherheit?','What is reporting measurement uncertainty?'],
    ['En brugbar usikkerhedsangivelse beskriver resultat, enhed, vurderingsmetode og relevante forbehold. Et løst plus/minus-tal uden grundlag er utilstrækkeligt. Når RavRadar ikke har dokumentation for en bestemt fejlprocent, skal assistenten sige det frem for at give et tilsyneladende præcist tal.',
     'Eine brauchbare Unsicherheitsangabe beschreibt Ergebnis, Einheit, Bewertungsmethode und relevante Einschränkungen. Ein unbegründeter Plus-Minus-Wert genügt nicht. Fehlt RavRadar der Nachweis einer bestimmten Fehlerquote, muss der Assistent das sagen statt eine scheinbar genaue Zahl zu liefern.',
     'A useful uncertainty report describes the result, unit, evaluation method and relevant limitations. An unsupported plus-or-minus number is insufficient. If RavRadar has no evidence for a particular error percentage, the assistant should say so instead of supplying a seemingly precise number.'],['nist-uncertainty-reporting']),
  concept('arithmetic-mean',[['aritmetisk gennemsnit'],['arithmetischer Mittelwert'],['arithmetic mean']],
    ['Hvad er et aritmetisk gennemsnit?','Was ist ein arithmetischer Mittelwert?','What is an arithmetic mean?'],
    ['Det aritmetiske gennemsnit er summen af værdierne delt med deres antal. Ekstreme værdier kan trække det væk fra et typisk resultat. Ved ravture skjuler et gennemsnit også fordelingen mellem tomme ture og store fund. Forklaringen ændrer ikke RavRadars rangering eller daglige score.',
     'Der arithmetische Mittelwert ist die Summe der Werte geteilt durch ihre Anzahl. Extremwerte können ihn vom typischen Ergebnis wegziehen. Bei Bernsteintouren verdeckt ein Mittelwert auch die Verteilung zwischen leeren Touren und großen Funden. Die Erklärung ändert weder RavRadars Rangfolge noch Tagesscores.',
     'The arithmetic mean is the sum of values divided by their count. Extreme values can pull it away from a typical result. For amber trips, a mean also hides the distribution between empty trips and large finds. This explanation changes neither RavRadar’s ranking nor its daily score.'],['nist-location-statistics']),
  concept('median',[['median'],['Median'],['median']],
    ['Hvad er en median?','Was ist ein Median?','What is a median?'],
    ['Medianen er den midterste værdi i en sorteret række; ved et lige antal bruges de to midterste værdiers gennemsnit. Den er mindre følsom for enkelte ekstreme fund end gennemsnittet, men beskriver ikke hele fordelingen. Den erstatter ikke RavRadars eksisterende prognose eller Top20.',
     'Der Median ist der mittlere Wert einer sortierten Reihe; bei gerader Anzahl nimmt man den Mittelwert der beiden mittleren Werte. Er reagiert weniger auf einzelne extreme Funde als der Mittelwert, beschreibt aber nicht die ganze Verteilung. Er ersetzt weder RavRadars Prognose noch Top20.',
     'The median is the middle value in a sorted series; with an even count, use the mean of the two middle values. It is less sensitive to individual extreme finds than the mean but does not describe the whole distribution. It replaces neither RavRadar’s forecast nor Top20.'],['nist-location-statistics']),
  concept('standard-deviation',[['standardafvigelse'],['Standardabweichung'],['standard deviation']],
    ['Hvad er en standardafvigelse?','Was ist eine Standardabweichung?','What is a standard deviation?'],
    ['Standardafvigelse beskriver spredning omkring gennemsnittet og har samme enhed som værdierne. Den er ikke i sig selv en sikkerhedsgrænse eller en fundchance. Et RavScore-interval er ikke dokumenteret som plus/minus én standardafvigelse; den fortolkning må assistenten ikke opfinde.',
     'Die Standardabweichung beschreibt Streuung um den Mittelwert und hat dieselbe Einheit wie die Werte. Sie ist allein weder Sicherheitsgrenze noch Fundchance. Ein RavScore-Intervall ist nicht als plus/minus eine Standardabweichung dokumentiert; diese Deutung darf der Assistent nicht erfinden.',
     'Standard deviation describes spread around the mean and uses the same unit as the values. It is not itself a safety boundary or a find probability. A RavScore interval is not documented as plus or minus one standard deviation; the assistant must not invent that interpretation.'],['nist-spread-statistics']),
  concept('variance',[['statistisk varians'],['statistische Varianz'],['statistical variance']],
    ['Hvad er statistisk varians?','Was ist statistische Varianz?','What is statistical variance?'],
    ['Varians er et spredningsmål baseret på kvadrerede afvigelser fra gennemsnittet; standardafvigelsen er dens kvadratrod. Enheden er derfor kvadreret. Det er ikke en ravprocent, og assistenten beregner ikke varians ud fra manglende data eller ændrer den faktiske scoreformel.',
     'Varianz ist ein Streuungsmaß aus quadrierten Abweichungen vom Mittelwert; die Standardabweichung ist ihre Quadratwurzel. Die Einheit ist daher quadriert. Sie ist keine Bernsteinquote; der Assistent berechnet keine Varianz aus fehlenden Daten und ändert keine Scoreformel.',
     'Variance measures spread using squared deviations from the mean; standard deviation is its square root. Its unit is therefore squared. It is not an amber percentage, and the assistant neither calculates variance from missing data nor changes the actual scoring formula.'],['nist-spread-statistics']),
  concept('interquartile-range',[['interkvartilbredde'],['Interquartilsabstand'],['interquartile range']],
    ['Hvad er en interkvartilbredde?','Was ist ein Interquartilsabstand?','What is an interquartile range?'],
    ['Interkvartilbredden er afstanden mellem første og tredje kvartil og beskriver den midterste del af en fordeling. Den er ikke hele minimum–maksimum-spændet. Ved sammenligning af turdata kan den være et metodebegreb, men den er ikke automatisk definitionen af RavRadars viste scoreinterval.',
     'Der Interquartilsabstand liegt zwischen dem ersten und dritten Quartil und beschreibt den mittleren Teil einer Verteilung. Er ist nicht die ganze Minimum-Maximum-Spanne. Bei Tourdaten ist er ein möglicher Methodenbegriff, aber nicht automatisch die Definition von RavRadars Scoreintervall.',
     'The interquartile range is the distance between the first and third quartiles, describing the middle part of a distribution. It is not the full minimum-to-maximum range. It can be a method concept for trip data, but it is not automatically the definition of RavRadar’s displayed score interval.'],['nist-spread-statistics']),
  concept('outlier',[['statistisk outlier','afvigende observation'],['statistischer Ausreißer'],['statistical outlier']],
    ['Hvad er en statistisk outlier?','Was ist ein statistischer Ausreißer?','What is a statistical outlier?'],
    ['En outlier skiller sig tydeligt ud fra de øvrige observationer. Den kan være en fejl eller en reel usædvanlig hændelse og skal undersøges, ikke automatisk slettes. Et stort ravfund eller en kraftig vejrhændelse må ikke fjernes alene, fordi det ikke ligner resten. Forklaringen ændrer ingen gemt historik.',
     'Ein Ausreißer hebt sich deutlich von anderen Beobachtungen ab. Er kann ein Fehler oder ein echtes seltenes Ereignis sein und muss untersucht, nicht automatisch gelöscht werden. Ein großer Bernsteinfund oder starkes Wetter darf nicht allein wegen seiner Abweichung entfernt werden. Diese Erklärung ändert keine gespeicherte Historie.',
     'An outlier stands apart from other observations. It may be an error or a real unusual event and needs investigation, not automatic deletion. A large amber find or strong weather event must not be removed merely for differing from the rest. This explanation changes no stored history.'],['nist-outlier-analysis']),
  concept('autocorrelation',[['autokorrelation'],['Autokorrelation'],['autocorrelation']],
    ['Hvad er autokorrelation?','Was ist Autokorrelation?','What is autocorrelation?'],
    ['Autokorrelation beskriver sammenhæng mellem en tidsserie og dens egne forskudte værdier. Nabotimer i et stormforløb kan derfor ikke uden videre regnes som uafhængige beviser. Mange RavRadar-timer er ikke det samme som mange uafhængige ture, og sammenhængen beviser ikke, at vejret skabte et bestemt fund.',
     'Autokorrelation beschreibt den Zusammenhang einer Zeitreihe mit ihren zeitversetzten eigenen Werten. Benachbarte Stunden eines Sturms sind daher nicht einfach unabhängige Belege. Viele RavRadar-Stunden entsprechen nicht vielen unabhängigen Touren; der Zusammenhang beweist auch keine Ursache eines bestimmten Fundes.',
     'Autocorrelation describes association between a time series and its own time-shifted values. Neighbouring storm hours cannot simply be treated as independent evidence. Many RavRadar hours do not equal many independent trips, and the association does not prove that weather caused a particular find.'],['nist-autocorrelation']),
  concept('upwelling',[['upwelling','opvældning'],['Upwelling','Auftrieb von Tiefenwasser'],['upwelling']],
    ['Hvad er upwelling?','Was ist Upwelling?','What is upwelling?'],
    ['Upwelling er opstrømning af vand fra dybere lag, som erstatter bortført overfladevand. Det kan påvirke vandets egenskaber, men er ikke det samme som at løfte rav fra bunden og levere det på stranden. Forklaringen diagnosticerer ikke upwelling ved din valgte zone eller ændrer RavRadars strømdata.',
     'Upwelling ist das Aufsteigen tieferen Wassers als Ersatz für verdrängtes Oberflächenwasser. Das kann Wassereigenschaften beeinflussen, hebt aber nicht automatisch Bernstein vom Boden an den Strand. Diese Erklärung diagnostiziert kein Upwelling in deiner Zone und ändert keine RavRadar-Strömungsdaten.',
     'Upwelling is deeper water rising to replace displaced surface water. It can affect water properties but is not the same as lifting seabed amber and delivering it to the beach. This explanation diagnoses no upwelling at your selected zone and changes no RavRadar current data.'],['noaa-upwelling-method']),
  concept('downwelling',[['downwelling','nedvældning'],['Downwelling'],['downwelling']],
    ['Hvad er downwelling?','Was ist Downwelling?','What is downwelling?'],
    ['Downwelling er nedsynkning af overfladevand, fx når vand samles mod en kyst. Det siger ikke alene, hvordan et ravstykke bevæger sig tæt ved bunden. Brug ikke ordet som en sikker leveringsregel; den aktuelle RavRadar-prognose og tegn på stranden er stadig særskilte oplysninger.',
     'Downwelling ist das Absinken von Oberflächenwasser, etwa wenn sich Wasser an einer Küste sammelt. Das allein beschreibt nicht die Bewegung eines Bernsteinstücks am Boden. Das Wort ist keine sichere Lieferregel; aktuelle RavRadar-Prognose und Spuren am Strand bleiben getrennte Informationen.',
     'Downwelling is surface water sinking, for example when water accumulates against a coast. It does not alone describe an amber piece’s near-bed movement. Do not use the term as a guaranteed delivery rule; the actual RavRadar forecast and beach signs remain separate information.'],['noaa-upwelling-method']),
  concept('coriolis',[['corioliseffekt','corioliseffekten'],['Corioliseffekt'],['Coriolis effect']],
    ['Hvad er corioliseffekten?','Was ist der Corioliseffekt?','What is the Coriolis effect?'],
    ['Corioliseffekten er en afbøjning knyttet til Jordens rotation, relevant for større strøm- og vejrsystemer. Den er ikke en enkel regel om, at alt rav eller al lokal strøm altid drejer til samme side. Kystform, bund, vind og bølger skal stadig skelnes; forklaringen vender ikke RavRadars pile.',
     'Der Corioliseffekt ist eine Ablenkung durch die Erdrotation und betrifft größere Strömungs- und Wettersysteme. Er bedeutet nicht, dass jeder Bernstein oder jede örtliche Strömung immer zur gleichen Seite dreht. Küstenform, Boden, Wind und Wellen bleiben wichtig; diese Erklärung dreht keine RavRadar-Pfeile.',
     'The Coriolis effect is deflection associated with Earth’s rotation, relevant to larger current and weather systems. It is not a simple rule that all amber or local flow always turns the same way. Coast shape, seabed, wind and waves still matter; this explanation reverses no RavRadar arrows.'],['noaa-coriolis-method']),
  concept('ekman',[['ekmanspiral','ekmanspiralen'],['Ekmanspirale','Ekman-Spirale'],['Ekman spiral']],
    ['Hvad er ekmanspiralen?','Was ist die Ekmanspirale?','What is the Ekman spiral?'],
    ['Ekmanspiralen er en idealiseret beskrivelse af, hvordan vind, friktion og Jordens rotation kan give forskellige strømretninger med dybden. Den kan ikke bruges som en fast drejevinkel ved alle danske strande. RavRadars strømpil er fortsat det verificerede modellag, ikke en beregning af en lokal spiral.',
     'Die Ekmanspirale beschreibt idealisiert, wie Wind, Reibung und Erdrotation unterschiedliche Strömungsrichtungen mit der Tiefe erzeugen können. Sie liefert keinen festen Drehwinkel für alle dänischen Strände. RavRadars Pfeil zeigt weiterhin die verifizierte Modellschicht, keine berechnete örtliche Spirale.',
     'The Ekman spiral is an idealised description of how wind, friction and Earth’s rotation can produce different current directions with depth. It supplies no fixed turning angle for every Danish beach. RavRadar’s current arrow remains the verified model layer, not a calculated local spiral.'],['noaa-ekman-method']),
  concept('windage',[['vindage','direkte vinddrift på flydende ting'],['Windage','direkte Winddrift schwimmender Objekte'],['windage','direct wind drift of floating objects']],
    ['Hvad er vindage?','Was ist Windage?','What is windage?'],
    ['Vindage er vindens direkte påvirkning af den del af en flydende genstand, som er over vandet. Det er forskelligt fra vindens påvirkning af selve vandstrømmen. Regler for olie eller flydende affald må ikke overføres som faste koefficienter til rav under vand; forklaringen tilføjer ingen sådan regel i RavRadar.',
     'Windage ist die direkte Windwirkung auf den über Wasser liegenden Teil eines schwimmenden Gegenstands. Das ist etwas anderes als die Windwirkung auf die Wasserströmung. Regeln für Öl oder schwimmenden Müll dürfen nicht als feste Koeffizienten auf untergetauchten Bernstein übertragen werden; RavRadar erhält keine solche Regel.',
     'Windage is direct wind action on the above-water part of a floating object. It differs from wind influencing the water current itself. Oil or floating-debris rules must not become fixed coefficients for submerged amber; this explanation introduces no such rule into RavRadar.'],['noaa-windage-method']),
  concept('discharge',[['vandføring'],['Abflussmenge'],['water discharge']],
    ['Hvad er vandføring?','Was ist eine Abflussmenge?','What is water discharge?'],
    ['Vandføring er vandvolumen pr. tid gennem et tværsnit, typisk i kubikmeter pr. sekund. Strømhastighed er derimod afstand pr. tid. RavRadars strømpil giver ikke en samlet vandføring gennem et sund, og høj vandstand alene kan ikke omsættes til en bestemt hastighed eller ravtransport.',
     'Abflussmenge ist Wasservolumen pro Zeit durch einen Querschnitt, etwa Kubikmeter pro Sekunde. Strömungsgeschwindigkeit ist dagegen Strecke pro Zeit. RavRadars Pfeil liefert keinen Gesamtfluss durch eine Meerenge; hoher Wasserstand allein ergibt weder eine bestimmte Geschwindigkeit noch Bernsteintransport.',
     'Discharge is water volume per time through a cross-section, commonly cubic metres per second. Current speed is distance per time. RavRadar’s current arrow does not supply total discharge through a strait, and high water level alone cannot be converted into a particular speed or amber transport.'],['usgs-discharge-method']),
  concept('adcp',[['ADCP','akustisk strømprofilering'],['ADCP','akustische Strömungsprofilierung'],['ADCP','acoustic current profiling']],
    ['Hvad er en ADCP?','Was ist ein ADCP?','What is an ADCP?'],
    ['En ADCP bruger Dopplerforskydning i ekkoer fra lydpulser til at undersøge vandets bevægelse i forskellige dybder. Det er et måleinstrument, ikke en ravdetektor. RavRadars modelpil må ikke kaldes en lokal ADCP-måling, medmindre der faktisk findes en dokumenteret sådan måling.',
     'Ein ADCP untersucht Wasserbewegung in verschiedenen Tiefen anhand der Dopplerverschiebung von Schallechos. Es ist ein Messinstrument, kein Bernsteindetektor. RavRadars Modellpfeil darf ohne tatsächlich dokumentierte Messung nicht als örtliche ADCP-Messung bezeichnet werden.',
     'An ADCP investigates water movement at different depths using Doppler shifts in acoustic echoes. It is a measuring instrument, not an amber detector. RavRadar’s model arrow must not be called a local ADCP measurement unless such a measurement is actually documented.'],['noaa-current-profiler']),
  concept('conductivity',[['vands elektriske ledningsevne'],['elektrische Leitfähigkeit von Wasser'],['electrical conductivity of water']],
    ['Hvad er vands elektriske ledningsevne?','Was ist die elektrische Leitfähigkeit von Wasser?','What is electrical conductivity of water?'],
    ['Elektrisk ledningsevne beskriver, hvor let vand leder elektrisk strøm; opløste ioner har betydning. Elektrisk strøm er ikke havets strømhastighed. Begrebet siger ikke alene, om et stykke er rav, og assistenten foreslår ikke forsøg med elektricitet i vand eller en ny RavScore-faktor.',
     'Elektrische Leitfähigkeit beschreibt, wie leicht Wasser elektrischen Strom leitet; gelöste Ionen spielen eine Rolle. Elektrischer Strom ist nicht die Meeresströmung. Der Begriff identifiziert allein keinen Bernstein; der Assistent schlägt weder Stromversuche im Wasser noch einen neuen RavScore-Faktor vor.',
     'Electrical conductivity describes how readily water conducts electric current; dissolved ions matter. Electric current is not ocean-current speed. The concept alone does not identify amber, and the assistant proposes neither electrical experiments in water nor a new RavScore factor.'],['usgs-conductivity']),
  concept('turbidity',[['turbiditet'],['Trübung'],['turbidity']],
    ['Hvad er turbiditet?','Was ist Trübung?','What is turbidity?'],
    ['Turbiditet er et optisk mål for vandets uklarhed, påvirket af lysspredning fra fx fine partikler og organismer. Det er ikke en optælling af rav. Uklart vand kan gøre det sværere at se, men hverken uklarhed eller klart vand beviser, hvor meget rav der ligger ved bunden.',
     'Trübung ist ein optisches Maß für unklares Wasser, beeinflusst etwa durch Lichtstreuung an feinen Partikeln und Organismen. Sie zählt keinen Bernstein. Trübes Wasser erschwert das Sehen; weder Trübung noch klares Wasser belegt die Bernsteinmenge am Boden.',
     'Turbidity is an optical measure of water cloudiness, affected by light scattering from fine particles and organisms, for example. It does not count amber. Cloudy water can hinder visibility, but neither cloudiness nor clear water proves how much amber lies on the seabed.'],['usgs-turbidity']),
  concept('suspended-sediment',[['suspenderet sediment'],['Schwebsediment'],['suspended sediment']],
    ['Hvad er suspenderet sediment?','Was ist Schwebsediment?','What is suspended sediment?'],
    ['Suspenderet sediment er materiale, der bæres i vandet i stedet for at ligge stille på bunden. En vandprøve kan undersøges for sedimentkoncentration. Brunligt vand er ikke en dokumenteret ravkoncentration, og en generel sedimentforklaring identificerer ikke det materiale, der transporteres ved din strand.',
     'Schwebsediment ist Material, das im Wasser getragen wird statt ruhig am Boden zu liegen. Eine Wasserprobe kann auf Sedimentkonzentration untersucht werden. Braunes Wasser belegt keine Bernsteinkonzentration; eine allgemeine Sedimenterklärung identifiziert nicht das Material an deinem Strand.',
     'Suspended sediment is material carried within water rather than resting on the bed. A water sample can be examined for sediment concentration. Brownish water is not a documented amber concentration, and a general sediment explanation does not identify material being transported at your beach.'],['usgs-suspended-sediment']),
  concept('sediment-load',[['sedimenttransport pr. tid'],['Sedimentfracht pro Zeit'],['sediment load per unit time']],
    ['Hvad er sedimenttransport pr. tid?','Was ist Sedimentfracht pro Zeit?','What is sediment load per unit time?'],
    ['Sedimenttransport pr. tid beskriver en masse, der passerer et sted i et tidsrum. Koncentration alene er ikke nok; også vandføring og repræsentative prøver har betydning. RavRadars strømhastighed kan derfor ikke ganges med et gættet ravlager og præsenteres som målte kilo rav på vej mod land.',
     'Sedimentfracht pro Zeit beschreibt eine Masse, die einen Ort während einer Zeitspanne passiert. Konzentration allein genügt nicht; Abfluss und repräsentative Proben sind ebenfalls nötig. RavRadars Geschwindigkeit darf daher nicht mit einem geratenen Bernsteinvorrat zu angeblich gemessenen Kilogramm Richtung Land verrechnet werden.',
     'Sediment load per unit time describes mass passing a location during a period. Concentration alone is insufficient; discharge and representative samples also matter. RavRadar’s current speed must not be multiplied by a guessed amber stock and presented as measured kilograms moving ashore.'],['usgs-suspended-sediment']),
  comparison('turbidity-concentration',[['turbiditet','Trübung','turbidity'],['sedimentkoncentration','Sedimentkonzentration','sediment concentration']],
    ['Hvad er forskellen på turbiditet og sedimentkoncentration?','Was ist der Unterschied zwischen Trübung und Sedimentkonzentration?','What is the difference between turbidity and sediment concentration?'],
    ['Turbiditet beskriver optisk uklarhed; sedimentkoncentration beskriver sedimentmængde i et vandvolumen. Samme uklarhed kan ikke universelt omsættes til samme masse. Ingen af delene giver alene ravmængde eller sikkerhed for at vade. RavRadar får ikke en ny lokal måling gennem denne begrebsforklaring.',
     'Trübung beschreibt optische Unklarheit; Sedimentkonzentration die Sedimentmenge in einem Wasservolumen. Gleiche Trübung lässt sich nicht allgemein in gleiche Masse umrechnen. Keine der Größen liefert allein Bernsteinmenge oder Watsicherheit. Diese Begriffserklärung gibt RavRadar keine neue örtliche Messung.',
     'Turbidity describes optical cloudiness; sediment concentration describes sediment quantity in a water volume. Equal cloudiness cannot universally be converted into equal mass. Neither alone supplies amber quantity or safe wading conditions. This explanation gives RavRadar no new local measurement.'],['usgs-turbidity','usgs-suspended-sediment']),
  concept('sediment-budget',[['sedimentbudget'],['Sedimentbudget'],['sediment budget']],
    ['Hvad er et sedimentbudget?','Was ist ein Sedimentbudget?','What is a sediment budget?'],
    ['Et sedimentbudget sammenholder tilførsel, borttransport og ændring i et områdes sedimentlager. Et positivt sandbudget er ikke automatisk et positivt ravbudget. RavRadar må ikke antage, at nyt sand indeholder rav, eller regne et lokalt ravlager ud uden dokumenteret grundlag.',
     'Ein Sedimentbudget vergleicht Zufuhr, Abtransport und Speicheränderung eines Gebiets. Ein positives Sandbudget bedeutet nicht automatisch ein positives Bernsteinbudget. RavRadar darf nicht annehmen, dass neuer Sand Bernstein enthält, oder ohne Nachweis einen örtlichen Bernsteinvorrat berechnen.',
     'A sediment budget compares input, removal and changes in sediment storage within an area. A positive sand budget is not automatically a positive amber budget. RavRadar must not assume new sand contains amber or calculate local amber stock without supporting evidence.'],['usgs-sediment-budget']),
  concept('erosion-accretion',[['kysterosion og aflejring'],['Küstenerosion und Ablagerung'],['coastal erosion and accretion']],
    ['Hvad er kysterosion og aflejring?','Was sind Küstenerosion und Ablagerung?','What are coastal erosion and accretion?'],
    ['Erosion fjerner kystmateriale; aflejring bygger materiale op. Begge kan ændre adgang til ældre lag og begrave eller blotlægge noget, men de skaber ikke i sig selv rav. En ændret strand er derfor et observationspunkt, ikke en fundgaranti eller bevis på, at RavRadars geometri skal ændres.',
     'Erosion trägt Küstenmaterial ab; Ablagerung baut es auf. Beides kann den Zugang zu älteren Schichten verändern und Material bedecken oder freilegen, erzeugt aber keinen Bernstein. Ein veränderter Strand ist daher eine Beobachtung, keine Fundgarantie und kein Beweis für nötige RavRadar-Geometrieänderungen.',
     'Erosion removes coastal material; accretion builds it up. Both can change access to older layers and bury or expose material, but neither creates amber. A changed beach is therefore something to observe, not a find guarantee or proof that RavRadar’s geometry needs changing.'],['usgs-sediment-budget']),
  concept('surface-drifter',[['overfladestrømdrifter'],['Oberflächenströmungsdrifter'],['surface-current drifter']],
    ['Hvad er en overfladestrømdrifter?','Was ist ein Oberflächenströmungsdrifter?','What is a surface-current drifter?'],
    ['En strømdrifter er et særligt instrument, som følger vandbevægelse i et bestemt lag. Flydende tang eller affald er ikke automatisk en sådan måling og kan påvirkes anderledes af vind og bølger. En overfladebane dokumenterer ikke ravets bundbane, og RavRadar bliver ikke en driftertjeneste af denne forklaring.',
     'Ein Strömungsdrifter ist ein spezielles Instrument, das Wasserbewegung in einer bestimmten Schicht folgt. Schwimmendes Seegras oder Müll ist nicht automatisch eine solche Messung und kann anders auf Wind und Wellen reagieren. Eine Oberflächenbahn belegt keinen Bernsteinweg am Boden; RavRadar wird dadurch kein Drifterdienst.',
     'A current drifter is a purpose-built instrument following water movement in a particular layer. Floating seaweed or litter is not automatically such a measurement and may respond differently to wind and waves. A surface track does not document amber’s bottom track, and this explanation does not make RavRadar a drifter service.'],['noaa-surface-drifter']),
  concept('hf-current-radar',[['HF-strømradar'],['HF-Strömungsradar'],['HF current radar']],
    ['Hvad er en HF-strømradar?','Was ist ein HF-Strömungsradar?','What is an HF current radar?'],
    ['En landbaseret HF-radar kan undersøge overfladestrøm med radiosignaler. Overfladestrøm er ikke en direkte måling af rav ved bunden. Navnet RavRadar betyder ikke, at hjemmesiden har en sådan radar; dens strømpil skal fortsat forklares ud fra den faktisk anvendte modelkilde.',
     'Ein landgestütztes HF-Radar kann Oberflächenströmung mit Funksignalen untersuchen. Oberflächenströmung ist keine direkte Messung von Bernstein am Boden. Der Name RavRadar bedeutet nicht, dass die Website ein solches Radar besitzt; ihr Pfeil bleibt anhand der tatsächlich verwendeten Modellquelle zu erklären.',
     'Land-based HF radar can investigate surface currents using radio signals. Surface current is not a direct measurement of seabed amber. The name RavRadar does not mean the website owns such a radar; its arrow must still be explained using the model source actually employed.'],['noaa-hf-current-radar']),
  concept('stage-discharge',[['vandstand-vandføring-relation'],['Wasserstand-Abfluss-Beziehung'],['stage-discharge relationship']],
    ['Hvad er en vandstand-vandføring-relation?','Was ist eine Wasserstand-Abfluss-Beziehung?','What is a stage-discharge relationship?'],
    ['En vandstand-vandføring-relation er en stedsspecifik sammenhæng etableret med målinger, især ved vandløb. Den afhænger af det lokale tværsnit og kan ændre sig. En sådan flodrelation må ikke bruges til at omregne RavRadars havvandstand til strøm eller ravlevering uden et særskilt dokumenteret grundlag.',
     'Eine Wasserstand-Abfluss-Beziehung ist ein örtlicher, durch Messungen bestimmter Zusammenhang, besonders an Flüssen. Sie hängt vom lokalen Querschnitt ab und kann sich ändern. Eine solche Flussbeziehung darf ohne gesonderten Nachweis RavRadars Meerwasserstand nicht in Strömung oder Bernsteinlieferung umrechnen.',
     'A stage-discharge relationship is a site-specific relation established through measurements, especially in rivers. It depends on the local cross-section and can change. Such a river relation must not convert RavRadar’s sea level into current or amber delivery without separate supporting evidence.'],['usgs-discharge-method']),
  concept('wave-runup',[['bølgeopløb'],['Wellenauflauf'],['wave runup']],
    ['Hvad er bølgeopløb?','Was ist Wellenauflauf?','What is wave runup?'],
    ['Bølgeopløb er bølgernes bevægelse op ad stranden over den rolige vandflade. Det omfatter både en bølgepåvirket middelvandstand og den skiftende skyllebevægelse. Bølger og strandens hældning har betydning. RavRadars viste vandstand er ikke en lokal beregning af, hvor langt hver bølge når; bølgehøjden må ikke blot lægges til som et sikkert opløb eller en sikker vadegrænse.',
     'Wellenauflauf ist das Auflaufen der Wellen am Strand über die ruhige Wasseroberfläche. Er umfasst eine wellenbedingte mittlere Erhöhung und die wechselnde Auflaufbewegung. Wellen und Strandneigung spielen eine Rolle. RavRadars Wasserstand berechnet nicht, wie weit jede örtliche Welle reicht; Wellenhöhe darf nicht einfach als sicherer Auflauf oder sichere Watgrenze addiert werden.',
     'Wave runup is waves reaching up the beach above the still-water surface. It includes a wave-induced mean elevation and time-varying swash. Waves and beach slope matter. RavRadar’s displayed water level is not a local calculation of how far each wave reaches; wave height must not simply be added as a certain runup or safe wading limit.'],['usgs-wave-runup-schematic','usgs-setup-swash-runup']),
  concept('wave-setup',[['bølgesetup'],['wellenbedingter Wasserstandsanstieg','Wave Setup'],['wave setup']],
    ['Hvad er bølgesetup?','Was ist wellenbedingter Wasserstandsanstieg?','What is wave setup?'],
    ['Bølgesetup er en lokal forhøjelse af middelvandstanden, som bølgepåvirkning kan skabe tæt ved kysten. Det er ikke den enkelte bølges skyl op ad stranden og ikke det samme som stormstuvning fra vind og lufttryk. Assistenten beregner ikke et ekstra setup-tal ved din zone og lægger ikke en udokumenteret forhøjelse oven i RavRadars eksisterende vandstand.',
     'Wellenbedingter Wasserstandsanstieg, auch Wave Setup, ist eine örtliche Erhöhung des mittleren Wasserstands durch Wellenwirkung an der Küste. Er ist weder der Auflauf einer einzelnen Welle noch Sturmstau durch Wind und Luftdruck. Der Assistent berechnet keinen zusätzlichen örtlichen Setup-Wert und addiert keine unbelegte Erhöhung zu RavRadars bestehendem Wasserstand.',
     'Wave setup is a local increase in mean water level caused by wave action near the coast. It is neither an individual wave’s swash up the beach nor storm surge driven by wind and air pressure. The assistant calculates no extra setup value at your zone and adds no unsupported elevation to RavRadar’s existing water level.'],['usgs-wave-runup-schematic','usgs-setup-swash-runup','noaa-surge-total']),
  concept('coastal-overwash',[['stormovervask'],['Sturmüberwaschung'],['storm overwash']],
    ['Hvad er stormovervask?','Was ist Sturmüberwaschung?','What is storm overwash?'],
    ['Stormovervask sker, når bølger skyller over en klittop eller kystbarriere og kan føre sand landværts. Det kan ske i gentagne skyl uden, at området hele tiden er under vand. Det fortæller ikke, at der er rav i sandet. RavRadar dokumenterer ikke bølgernes lokale rækkevidde eller en sikker passage over en klit; hold afstand til en kyst, der overskylles.',
     'Sturmüberwaschung entsteht, wenn Wellen über eine Düne oder Küstenbarriere laufen und Sand landwärts transportieren können. Wiederholte Überläufe müssen keine dauerhafte Überflutung sein. Sie belegen keinen Bernstein im Sand. RavRadar dokumentiert weder die örtliche Wellenreichweite noch einen sicheren Dünenübergang; halte Abstand zu überspülten Küsten.',
     'Storm overwash occurs when waves pass over a dune crest or coastal barrier and can carry sand landward. Repeated overtopping does not require continuous submersion. It does not establish that the sand contains amber. RavRadar documents neither local wave reach nor a safe dune crossing; stay away from an overtopped coast.'],['usgs-storm-impact-regimes','usgs-storm-impact-scale']),
  concept('coastal-inundation',[['vedvarende kystoversvømmelse'],['Küstenüberflutung','anhaltende Küstenüberflutung'],['coastal inundation']],
    ['Hvad er vedvarende kystoversvømmelse?','Was ist Küstenüberflutung?','What is coastal inundation?'],
    ['Ved vedvarende kystoversvømmelse står vandet over et kystområde eller en lav barriere i længere tid, ikke blot under enkelte bølgeskyl. Tidevand og stormstuvning kan bidrage. At vurdere det lokalt kræver også terræn og relevante varsler. RavRadars zonevandstand er ikke et oversvømmelseskort eller en garanti for, at din adgangsvej er fri.',
     'Bei anhaltender Küstenüberflutung steht Wasser länger über einem Küstenbereich oder einer niedrigen Barriere, nicht nur während einzelner Wellenüberläufe. Gezeiten und Sturmstau können beitragen. Für örtliche Aussagen sind auch Gelände und aktuelle Warnungen nötig. RavRadars Zonenwasserstand ist weder eine Überflutungskarte noch eine Garantie für einen freien Zugangsweg.',
     'Coastal inundation means water persistently covering coastal land or a low barrier, rather than only during individual wave overtopping. Tides and storm surge can contribute. Local assessment also needs terrain and relevant warnings. RavRadar’s zone water level is not a flood map or a guarantee that your access route is clear.'],['usgs-storm-impact-regimes','usgs-storm-impact-scale']),
  concept('dune-collision',[['klitkollision','bølgeangreb på klitfoden'],['Wellenangriff am Dünenfuß'],['dune collision']],
    ['Hvad er klitkollision?','Was ist Wellenangriff am Dünenfuß?','What is dune collision?'],
    ['Klitkollision beskriver bølger, der når klitfoden og kan erodere den. Bølgerne behøver ikke at passere over klittoppen. En stejl eller undermineret klit er ikke et sikkert sted at stå, og ny erosion er ikke bevis på rav. RavRadar klassificerer ikke lokale klitter efter denne skala og ændrer ikke zonernes geometri ud fra begrebet.',
     'Wellenangriff am Dünenfuß bedeutet, dass Wellen den Fuß der Düne erreichen und erodieren können. Sie müssen dabei nicht über den Dünenkamm laufen. Eine steile oder unterhöhlte Düne ist kein sicherer Standplatz; neue Erosion belegt keinen Bernstein. RavRadar klassifiziert örtliche Dünen nicht nach dieser Skala und verändert dadurch keine Zonengeometrie.',
     'Dune collision describes waves reaching and potentially eroding the dune toe. They need not pass over the dune crest. A steep or undercut dune is not a safe place to stand, and fresh erosion does not prove amber is present. RavRadar does not classify local dunes using this scale or alter zone geometry from the concept.'],['usgs-storm-impact-regimes','usgs-storm-impact-scale']),
  concept('barrier-island',[['barriereø'],['Barriereinsel'],['barrier island']],
    ['Hvad er en barriereø?','Was ist eine Barriereinsel?','What is a barrier island?'],
    ['En barriereø er en ofte lav, langstrakt sedimentø mellem åbent vand og et bagvedliggende kystområde. Bølger, strøm og sedimenttransport kan ændre den. Begrebet siger ikke, hvor meget rav der findes, eller om en bestemt dansk zone har denne form. RavRadar får ikke en ny automatisk kystklassifikation eller punktplacering af forklaringen.',
     'Eine Barriereinsel ist eine häufig niedrige, langgestreckte Sedimentinsel zwischen offenem Wasser und einem dahinterliegenden Küstenbereich. Wellen, Strömung und Sedimenttransport können sie verändern. Das Wort belegt weder eine Bernsteinmenge noch diese Form für eine bestimmte dänische Zone. Die Erklärung ergänzt keine automatische Küstenklassifikation oder Punktplatzierung in RavRadar.',
     'A barrier island is an often low, elongated sediment island between open water and a coastal area behind it. Waves, currents and sediment transport can change it. The term establishes neither amber quantity nor that a particular Danish zone has this form. This explanation adds no automatic coastal classification or point placement to RavRadar.'],['usgs-sediment-management']),
  concept('barrier-rollover',[['landværts barrierevandring'],['landwärtige Barrierewanderung'],['landward barrier rollover']],
    ['Hvad er landværts barrierevandring?','Was ist landwärtige Barrierewanderung?','What is landward barrier rollover?'],
    ['Landværts barrierevandring beskriver, at en kystbarrieres sediment og form flyttes ind mod land, blandt andet gennem overvask. Det er en ændring over tid, ikke en regel om, at alle kyster altid flytter samme vej. Sandets bevægelse dokumenterer ikke ravets bane eller en kommende fundplads. Assistenten forudsiger ikke en lokal barrierevandring ud fra RavScore.',
     'Landwärtige Barrierewanderung beschreibt die Verlagerung von Sediment und Form einer Küstenbarriere zum Land, unter anderem durch Überwaschung. Das ist eine zeitliche Veränderung, keine Regel, dass jede Küste immer in dieselbe Richtung wandert. Sandbewegung belegt weder den Weg von Bernstein noch einen künftigen Fundort. RavScore wird dadurch nicht zur örtlichen Wanderungsprognose.',
     'Landward barrier rollover describes coastal-barrier sediment and morphology shifting landward, including through overwash. It is change over time, not a rule that every coast always moves the same way. Sand movement does not document amber’s path or a future find location. The assistant does not predict local barrier migration from RavScore.'],['usgs-storm-impact-scale','usgs-sediment-management']),
  concept('beach-nourishment',[['sandfodring'],['Strandaufspülung'],['beach nourishment']],
    ['Hvad er sandfodring?','Was ist Strandaufspülung?','What is beach nourishment?'],
    ['Sandfodring er tilførsel af sand til en strand eller kyst, fx for at vedligeholde stranden eller dæmpe erosion. Virkningen afhænger af materialet og det lokale sedimentmiljø og er ikke nødvendigvis varig. Tilført sand er ikke dokumenteret ravholdigt. RavRadar har ikke automatisk oplysninger om alle sandfodringer; ændret strandform kræver konkrete observationer, ikke en gættet scorebonus.',
     'Strandaufspülung ist die gezielte Zugabe von Sand an Strand oder Küste, etwa zur Strandpflege oder Erosionsminderung. Die Wirkung hängt vom Material und örtlichen Sedimentsystem ab und ist nicht unbedingt dauerhaft. Zugeführter Sand enthält nicht nachweislich Bernstein. RavRadar kennt nicht automatisch alle Aufspülungen; veränderte Strandformen verlangen Beobachtungen statt eines geratenen Scorebonus.',
     'Beach nourishment is deliberately adding sand to a beach or coast, for example to maintain it or reduce erosion. Its effect depends on the material and local sediment setting and need not be permanent. Placed sand is not established to contain amber. RavRadar does not automatically know every nourishment project; changed beach form needs observations, not a guessed score bonus.'],['usgs-sediment-management']),
  comparison('runup-level',[['bølgeopløb','Wellenauflauf','wave runup'],['vandstand','Wasserstand','water level']],
    ['Hvad er forskellen på bølgeopløb og vandstand?','Was ist der Unterschied zwischen Wellenauflauf und Wasserstand?','What is the difference between wave runup and water level?'],
    ['Bølgeopløb og vandstand er forskellige størrelser. Vandstanden beskriver vandfladens niveau mod et referencegrundlag; bølgeopløb beskriver bølgernes rækkevidde op ad stranden i forhold til den rolige vandflade. Strandhældning og bølger har betydning. RavRadars viste vandstand er ikke et mål for hvert bølgeskyl, og du kan ikke få en sikker vadegrænse ved bare at lægge bølgehøjden til.',
     'Wellenauflauf und Wasserstand sind unterschiedliche Größen. Wasserstand beschreibt die Höhe der Wasseroberfläche gegenüber einem Bezug; Wellenauflauf die Reichweite der Wellen am Strand gegenüber ruhigem Wasser. Strandneigung und Wellen spielen eine Rolle. RavRadars Wasserstand misst nicht jeden Wellenüberlauf; einfach Wellenhöhe zu addieren ergibt keine sichere Watgrenze.',
     'Wave runup and water level are different quantities. Water level describes the elevation of the surface against a reference; runup describes waves reaching up the beach relative to still water. Beach slope and waves matter. RavRadar’s water level does not measure each wave’s reach, and simply adding wave height cannot give a safe wading limit.'],['usgs-wave-runup-schematic','usgs-setup-swash-runup']),
  comparison('setup-surge',[['bølgesetup','Wave Setup','wave setup'],['stormstuvning','Sturmstau','storm surge']],
    ['Hvad er forskellen på bølgesetup og stormstuvning?','Was ist der Unterschied zwischen Wave Setup und Sturmstau?','What is the difference between wave setup and storm surge?'],
    ['Bølgesetup er bølgepåvirkningens bidrag til den lokale middelvandstand ved kysten; stormstuvning er vandstandsændringen fra vejr som vind og lufttryk. De er forskellige processer og kan forekomme samtidig. Assistenten opdeler ikke RavRadars vandstand i disse bidrag og lægger ikke automatisk et ekstra tal oven i en eksisterende samlet modelværdi.',
     'Wave Setup ist der Beitrag der Wellenwirkung zum örtlichen mittleren Wasserstand an der Küste; Sturmstau ist die wetterbedingte Änderung etwa durch Wind und Luftdruck. Es sind unterschiedliche Prozesse, die gleichzeitig auftreten können. Der Assistent zerlegt RavRadars Wasserstand nicht in diese Beiträge und addiert keinen automatischen Zusatz zu einem bestehenden Gesamtmodellwert.',
     'Wave setup is wave action’s contribution to local mean water level near the coast; storm surge is the weather-driven change from factors such as wind and air pressure. They are different processes and can occur together. The assistant does not split RavRadar’s water level into these contributions or automatically add an extra value to an existing total model level.'],['usgs-wave-runup-schematic','usgs-storm-impact-regimes','noaa-surge-total']),
  comparison('overwash-inundation',[['stormovervask','Sturmüberwaschung','storm overwash'],['vedvarende kystoversvømmelse','Küstenüberflutung','coastal inundation']],
    ['Hvad er forskellen på stormovervask og vedvarende kystoversvømmelse?','Was ist der Unterschied zwischen Sturmüberwaschung und Küstenüberflutung?','What is the difference between storm overwash and coastal inundation?'],
    ['Stormovervask er bølger, som passerer over en klit eller barriere i skyl. Vedvarende kystoversvømmelse er, når vandet bliver stående over et kystområde eller en lav barriere. Begge afhænger af den lokale kystform og kan være farlige. RavRadar er ikke et kort over disse hændelser, og forskellen fortæller ikke, hvor der med sikkerhed kan findes rav eller gås sikkert.',
     'Sturmüberwaschung bedeutet einzelne Wellenüberläufe über Düne oder Barriere. Bei anhaltender Küstenüberflutung bleibt Wasser über einem Küstenbereich oder einer niedrigen Barriere stehen. Beides hängt von der örtlichen Küstenform ab und kann gefährlich sein. RavRadar kartiert diese Ereignisse nicht; die Unterscheidung garantiert weder Bernsteinfunde noch sicheren Zugang.',
     'Storm overwash means waves overtopping a dune or barrier in swashes. Coastal inundation means water persistently covering coastal land or a low barrier. Both depend on local coastal form and can be dangerous. RavRadar does not map these events, and the distinction guarantees neither amber finds nor safe access.'],['usgs-storm-impact-regimes','usgs-storm-impact-scale']),
  comparison('nourishment-accretion',[['sandfodring','Strandaufspülung','beach nourishment'],['naturlig aflejring','Ablagerung','natural accretion']],
    ['Hvad er forskellen på sandfodring og naturlig aflejring?','Was ist der Unterschied zwischen Strandaufspülung und Ablagerung?','What is the difference between beach nourishment and natural accretion?'],
    ['Sandfodring er en bevidst tilførsel af materiale; naturlig aflejring er opbygning gennem kystens egen sedimenttransport. Begge kan ændre stranden, men materialets oprindelse og videre bevægelse kan være forskellige. Ingen af delene dokumenterer ravmængde. Assistenten udleder ikke en sandfodringshistorik eller ændrer RavScore, blot fordi stranden ser bredere ud.',
     'Strandaufspülung ist die gezielte Zugabe von Material; natürliche Ablagerung entsteht durch den eigenen Sedimenttransport der Küste. Beides kann den Strand verändern, doch Herkunft und weitere Bewegung des Materials können verschieden sein. Keines belegt eine Bernsteinmenge. Ein breiterer Strand lässt den Assistenten weder eine Aufspülungshistorie erfinden noch RavScore ändern.',
     'Beach nourishment deliberately adds material; natural accretion builds up material through the coast’s own sediment transport. Both can change a beach, but material origin and subsequent movement may differ. Neither establishes amber quantity. A wider-looking beach does not make the assistant invent a nourishment history or change RavScore.'],['usgs-sediment-management','usgs-sediment-budget']),
  concept('measurand',[['målestørrelse'],['Messgröße'],['measurand']],
    ['Hvad er en målestørrelse?','Was ist eine Messgröße?','What is a measurand?'],
    ['Målestørrelsen er præcis det, man vil måle. Sted, tidspunkt, dybde og metode kan være nødvendige for at definere den. En modelstrøm ved et havpunkt, en overfladeobservation og en ravjægers fund er forskellige størrelser; de må ikke præsenteres som samme måling eller direkte erstatte hinanden.',
     'Die Messgröße ist genau das, was gemessen werden soll. Ort, Zeit, Tiefe und Methode können zur Definition nötig sein. Modellströmung am Meerespunkt, Oberflächenbeobachtung und Bernsteinfund sind verschiedene Größen; sie dürfen nicht als dieselbe Messung dargestellt werden oder einander direkt ersetzen.',
     'The measurand is precisely the quantity intended to be measured. Location, time, depth and method may be needed to define it. Model current at a sea point, a surface observation and an amber find are different quantities; they must not be presented as the same measurement or directly replace each other.'],['nist-measurement-terminology']),
]);

export const RAV_ASSISTANT_METHOD_EXAMPLES=Object.freeze(Object.fromEntries(
  RAV_ASSISTANT_METHOD_GUIDE.map(item=>[item.id,item.examples])));

function escapeTerms(terms){
  return '(?:'+terms.map(term=>term.split(' ').map(word=>word
    .replace(/[.*+?^${}()|[\]\\]/gu,'\\$&')).join(String.raw`\s+`)).join('|')+')';
}
function concept(id,terms,examples,answers,sourceIds){
  const [da,de,en]=terms.map(escapeTerms);
  const daTerm=String.raw`(?:(?:en|et|den|det)\s+)?${da}`;
  const deTerm=String.raw`(?:(?:ein|eine|der|die|das)\s+)?${de}`;
  const enTerm=String.raw`(?:(?:a|an|the)\s+)?${en}`;
  const requests=[
    String.raw`(?:(?:hvad\s+(?:er|betyder)|forklar(?:\s+mig)?|fortæl(?:\s+mig)?\s+om|(?:kan|kunne|vil)\s+du\s+(?:venligst\s+)?forklare)\s+)?${daTerm}`,
    String.raw`(?:(?:was\s+(?:ist|sind|bedeutet)|erkläre(?:\s+mir)?|erzähl(?:\s+mir)?\s+etwas\s+über)\s+)?${deTerm}`,
    String.raw`(?:kannst|könntest)\s+du\s+(?:bitte\s+)?${deTerm}\s+erklären`,
    String.raw`(?:(?:what\s+(?:is|are)|explain(?:\s+to\s+me)?|tell\s+me\s+about|(?:can|could|would)\s+you\s+(?:please\s+)?explain)\s+)?${enTerm}`,
  ];
  return entry(id,new RegExp('^(?:'+requests.join('|')+')[.!?\\s]*$','iu'),terms,examples,answers,sourceIds);
}
function comparison(id,pairs,examples,answers,sourceIds){
  const requests=['da','de','en'].flatMap((language,index)=>{
    const a=escapeTerms([pairs[0][index]]),b=escapeTerms([pairs[1][index]]);
    return [[a,b],[b,a]].flatMap(([first,second])=>language==='da'
      ? [String.raw`hvad\s+er\s+forskellen\s+(?:på|mellem)\s+${first}\s+og\s+${second}`,
        String.raw`(?:kan\s+du\s+(?:venligst\s+)?)?forklar(?:e)?\s+forskellen\s+(?:på|mellem)\s+${first}\s+og\s+${second}`,
        String.raw`er\s+${first}\s+(?:det\s+)?samme\s+som\s+${second}`]
      : language==='de'
        ? [String.raw`was\s+ist\s+der\s+unterschied\s+zwischen\s+${first}\s+und\s+${second}`,
          String.raw`erkläre\s+(?:mir\s+)?den\s+unterschied\s+zwischen\s+${first}\s+und\s+${second}`,
          String.raw`ist\s+${first}\s+dasselbe\s+wie\s+${second}`]
        : [String.raw`what\s+is\s+the\s+difference\s+between\s+${first}\s+and\s+${second}`,
          String.raw`(?:can\s+you\s+(?:please\s+)?)?explain\s+the\s+difference\s+between\s+${first}\s+and\s+${second}`,
          String.raw`is\s+${first}\s+(?:the\s+)?same\s+as\s+${second}`]);
  });
  return entry(id,new RegExp('^(?:'+requests.join('|')+')[.!?\\s]*$','iu'),null,examples,answers,sourceIds);
}
function entry(id,pattern,terms,examples,answers,sourceIds){
  const sources=[...sourceIds,'rr-current-product'];
  if(!validateRavAssistantSourceIds(sources))throw new Error('Unknown method-guide source: '+id);
  return Object.freeze({id:'learn-'+id,pattern,evidenceClass:'mixed',
    terms:terms?Object.freeze(terms.map(values=>Object.freeze(values))):null,
    sourceIds:Object.freeze(sources),examples:Object.freeze(examples),
    answers:Object.freeze(Object.fromEntries(['da','de','en'].map((language,index)=>[language,answers[index]])))});
}
